import sys, json, time, random, math
import numpy as np

def cost(p, A, B):
    total = 0
    n = len(p)
    for i in range(n):
        for j in range(i+1, n):
            total += A[i][j] * B[p[i]][p[j]]
    return total

def neighbor(p, A, B):
    n = len(p)
    i, j = sorted(random.sample(range(n), 2))
    new_p = p[:]
    new_p[i], new_p[j] = new_p[j], new_p[i]
    return new_p, cost(new_p, A, B)

def simulated_annealing(A, B, start_temp, end_temp, schedule_type, time_limit):
    n = len(A)
    current = list(range(n))
    current_cost = cost(current, A, B)
    best = current[:]
    best_cost = current_cost
    start_time = time.time()
    T = start_temp

    def temperature(t):
        elapsed = time.time() - start_time
        if elapsed >= time_limit:
            return 0.0
        if schedule_type == 'linear':
            return start_temp * (1 - elapsed / time_limit)
        elif schedule_type == 'log':
            return start_temp / (1 + math.log1p(elapsed))
        else:
            return start_temp * math.exp(-elapsed / (0.1 * time_limit))

    while True:
        elapsed = time.time() - start_time
        if elapsed >= time_limit:
            break
        T = temperature(elapsed)
        if T <= 0:
            break
        new_p, new_cost = neighbor(current, A, B)
        delta = new_cost - current_cost
        if delta < 0 or random.random() < math.exp(-delta / T):
            current, current_cost = new_p, new_cost
            if current_cost < best_cost:
                best, best_cost = current[:], current_cost
        if random.random() < 0.001:
            current = list(range(n))
            current_cost = cost(current, A, B)
            if current_cost < best_cost:
                best, best_cost = current[:], current_cost
    return best

def main():
    if len(sys.argv) < 3:
        return
    json_path = sys.argv[1]
    time_limit = float(sys.argv[2])
    if 'QAP_TIME_LIMIT_S' in os.environ:
        time_limit = min(time_limit, float(os.environ['QAP_TIME_LIMIT_S']))
    with open(json_path) as f:
        data = json.load(f)
    n = data['n']
    A = np.array(data['A'], dtype=int)
    B = np.array(data['B'], dtype=int)
    start_temp = 1e4
    end_temp = 1e-3
    schedule = 'log'
    perm = simulated_annealing(A, B, start_temp, end_temp, schedule, time_limit)
    print('PERMUTATION: ' + ' '.join(str(x+1) for x in perm))

if __name__ == '__main__':
    import os
    main()
